#include "support/process.hpp"
using namespace test;
int main(int argc,char** argv){try{
 if(const char* report=std::getenv("NANO_TEST_ENV_REPORT")){Json leaked=Json::array();for(const char* name:{"VALIDATOR_KEY","NANO_PRIVATE_KEY","NANO_MNEMONIC","NANO_HD_PASSPHRASE","NANO_WALLET_PASSWORD"})if(std::getenv(name))leaked.push_back(name);const char* token=std::getenv("NANO_NETWORK_TOKEN");save(report,{{"leaked",leaked},{"transport_token",token&&*token}});return 0;}
 check(argc==3,"core and network required");std::string core=argv[1],network=argv[2];Temp root;auto genesis=root/"genesis.json";save(genesis,{{"config",{{"chainId",1337},{"consensus","pos"}}}});
 auto report=root/"environment.json",probe=root/"probe.json";save(probe,{{"rpc_port",0},{"p2p_binary",fs::absolute(argv[0]).string()}});Env env={{"NANO_TEST_ENV_REPORT",report.string()}};for(auto name:{"VALIDATOR_KEY","NANO_PRIVATE_KEY","NANO_MNEMONIC","NANO_HD_PASSPHRASE","NANO_WALLET_PASSWORD"})env[name]="synthetic-secret-do-not-use";
 auto checked=run({core,"run",genesis.string(),(root/"probe-db").string(),probe.string()},env);check(checked.code==1,checked.err);check(load(report)==Json{{"leaked",Json::array()},{"transport_token",true}},"transport inherited secrets or lacks token");
 auto config=[&](const std::string& name,Json seeds){auto file=root/(name+".json");save(file,{{"rpc_port",0},{"p2p_port",0},{"p2p_host","127.0.0.1"},{"p2p_binary",network},{"bootnodes",seeds}});return file.string();};
 Process a({core,"run",genesis.string(),(root/"a").string(),config("a",Json::array())});int pa=a.port();std::string address=a.event("listen")["address"];int pid_a=a.event("p2p-process")["pid"];until([&]{return rpc(pa,"net_listening").get<bool>();},"transport listening");
 Process b({core,"run",genesis.string(),(root/"b").string(),config("b",{address})});int pb=b.port();b.event("listen");int pid_b=b.event("p2p-process")["pid"];until([&]{return rpc(pa,"net_peerCount")=="0x1"&&rpc(pb,"net_peerCount")=="0x1";},"connected peers visible");check(rpc(pa,"nno_getNetworkInfo")["node"]["peerId"]==address.substr(address.rfind("/p2p/")+5)&&rpc(pb,"nno_getNodes")["totalPeers"]==1,"network identity telemetry");
 for(int i=0;i<2;++i)check(rpc(pa,"validator_submitBlock",{rpc(pa,"validator_getBlockTemplate",{bootstrap})})["success"],"produce managed block");until([&]{return rpc(pb,"eth_blockNumber")=="0x2"&&rpc(pb,"eth_syncing")==false;},"managed history synchronized");check(rpc(pb,"validator_getSyncStatus")["networkConnected"],"sync connectivity");check(b.stop().code==0,"managed shutdown failed");until([&]{return kill(pid_b,0)<0&&errno==ESRCH;},"P2P child reaped");until([&]{return rpc(pa,"net_peerCount")=="0x0";},"peer removed from telemetry");check(kill(pid_a,SIGKILL)==0,"kill transport");check(a.wait(7).code==1,"core did not report child failure");check(success(run({core,"status",genesis.string(),(root/"a").string()}))["blockNumber"]=="0x2","chain lost after child failure");std::cout<<"Native supervisor scenarios passed\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
